<script>
 import { onMount,tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { keynoteSession,keynoteDocument,keynoteAvailability } from './keynote-state.js';
 import { keynoteMenus } from './keynote-menus.js';
 import { createKeynoteNativeView } from './keynote-native-view.js';
 import { keynoteSlideSVG,keynotePinGraph } from './keynote-engine.js';
 import './keynote.css';
 import {createDocumentFonts} from './document-fonts.svelte.js';
 let {state: keynoteState,profile,window:actualWindow=null,windowId=actualWindow?.id,controller,execute=null,oncommand=null,registerView=null,available=true,active=true,controls={},getShared=name=>controls.getShared?.(name),getFile=id=>controls.getFile?.(id)}=$props();
 let root=$state(null),message=$state(''),exportFormat=$state('pptx'),exportName=$state('Presentation'),theme=$state('white'),title=$state('Untitled'),drag=$state(null);
 let originalState,originalProfile,originalWindow,originalWindowId,originalController,originalSession,retired=false;
 const session=$derived(keynoteSession(keynoteState,windowId)),doc=$derived(keynoteDocument(keynoteState,session?.documentId)),slide=$derived(doc?.content.slides.find(s=>s.id===session?.slideId)),object=$derived(slide?.objects.find(o=>o.id===session?.objectId)),cap=$derived(keynoteAvailability(profile)),menus=$derived(keynoteMenus(profile,keynoteState,windowId));
 const themes=[{id:'white',label:'White',color:'#fff',ink:'#222'},{id:'black',label:'Black',color:'#17191c',ink:'#fff'},{id:'gradient',label:'Gradient',color:'#e9eff5',ink:'#222'},{id:'showcase',label:'Showcase',color:'#17191c',ink:'#ddd'}];
 function owned(){return !retired&&root?.isConnected===true&&keynoteState===originalState&&profile===originalProfile&&actualWindow===originalWindow&&windowId===originalWindowId&&controller===originalController&&session===originalSession;}
 async function request(command,target,payload={}){if(!owned()||!available||!active)return;const runner=oncommand??execute;const result=runner?await runner(command,target,payload):await controller?.handlers?.[command]?.(target,payload);if(owned())message=result?.status==='applied'?'':result?.error?.message??'The original native operation is unavailable.';return result;}
 const run=(name,payload={})=>request(`keynote.${name}`,{windowId},payload);
 const update=values=>run('object.update',{values});
 function chartURL(o){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(keynoteSlideSVG({width:o.width,height:o.height},{background:slide.background,objects:[{...o,x:0,y:0,rotation:0}]}));}
 function thumbnailSVG(s){void documentFonts.revision;return keynoteSlideSVG(doc.content,{...s,objects:s.objects.filter(o=>!['audio','video'].includes(o.type))},(name,bold,italic)=>documentFonts.css(name,bold,italic));}
 function position(o){const x=drag?.id===o.id?drag.x:o.x,y=drag?.id===o.id?drag.y:o.y;return `left:${x/doc.content.width*100}%;top:${y/doc.content.height*100}%;width:${o.width/doc.content.width*100}%;height:${o.height/doc.content.height*100}%;opacity:${o.opacity};transform:rotate(${o.rotation}deg);`;}
 function pointerStart(event,o){if(!owned()||!available||!active||session.presenting||['TEXTAREA','INPUT','VIDEO','AUDIO'].includes(event.target.tagName)||event.target.closest('.keynote-media-select'))return;event.preventDefault();const canvas=event.currentTarget.closest('[data-keynote-slide-canvas]'),rect=canvas.getBoundingClientRect(),pin=keynotePinGraph(o);drag={id:o.id,original:o,slide,doc,pin,startX:event.clientX,startY:event.clientY,x:o.x,y:o.y,originalX:o.x,originalY:o.y,scale:doc.content.width/rect.width,pointer:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId);}
 function pointerMove(event){if(!drag||event.pointerId!==drag.pointer||!owned())return;drag.x=Math.max(-960,Math.min(1920,drag.originalX+(event.clientX-drag.startX)*drag.scale));drag.y=Math.max(-960,Math.min(1920,drag.originalY+(event.clientY-drag.startY)*drag.scale));}
 async function pointerEnd(event){if(!drag||event.pointerId!==drag.pointer)return;const moving=drag;drag=null;if(!owned()||slide!==moving.slide||doc!==moving.doc||!slide.objects.includes(moving.original)||!moving.pin())return;if(session.objectId!==moving.id){const selected=await run('object.select',{objectId:moving.id});if(selected?.status!=='applied'||!owned()||doc!==moving.doc||slide!==moving.slide||!moving.pin())return;}if(moving.x!==moving.originalX||moving.y!==moving.originalY)await update({x:moving.x,y:moving.y});}
 function key(event){if(event.defaultPrevented||!owned()||!available||!active)return;if(!cap.windows&&event.metaKey&&!event.ctrlKey&&!event.altKey&&event.key.toLowerCase()==='q'){event.preventDefault();event.stopPropagation();request('app.quit',{appId:cap.appId},{});return;}const typing=['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||event.target.isContentEditable;if(session.presenting){if(event.key==='Escape'){event.preventDefault();run('present',{playing:false});return;}if(typing||['VIDEO','AUDIO'].includes(event.target.tagName)||event.target.closest('.keynote-presentation-bar button'))return;const direction=['ArrowRight','ArrowDown',' ','Enter','PageDown'].includes(event.key)?'next':['ArrowLeft','ArrowUp','PageUp'].includes(event.key)?'previous':event.key==='Home'?'first':event.key==='End'?'last':null;if(direction){event.preventDefault();run('present.step',{direction});}return;}
 if((event.metaKey||event.ctrlKey)&&!event.altKey){const k=event.key.toLowerCase();if(k==='s'){event.preventDefault();event.shiftKey?run('panel',{panel:'save'}):run('save');}else if(k==='o'){event.preventDefault();run('open');}else if(k==='n'){event.preventDefault();run('panel',{panel:'themes'});}else if(!typing&&k==='z'){event.preventDefault();run(event.shiftKey?'redo':'undo');}else if(!typing&&k==='c'){event.preventDefault();run('copy');}else if(!typing&&k==='v'){event.preventDefault();run('paste');}}
 if(event.key==='Escape'){drag=null;run('panel',{panel:'none'});run('menu',{menuId:null});}if(typing)return;if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();if(object)run('object.delete');}if(object&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const n=event.shiftKey?10:1;update({x:object.x+(event.key==='ArrowLeft'?-n:event.key==='ArrowRight'?n:0),y:object.y+(event.key==='ArrowUp'?-n:event.key==='ArrowDown'?n:0)});}if(event.key==='F5'){event.preventDefault();run('present',{playing:true});}}
 function mediaLoaded(event,o){if(!owned()||!slide?.objects.includes(o))return;const media=event.currentTarget;media.volume=o.volume;media.currentTime=o.trimStart;}
 function mediaTime(event,o){if(!owned()||!slide?.objects.includes(o)){event.currentTarget.pause();return;}const media=event.currentTarget;if(media.currentTime>=o.trimEnd){if(o.loop){media.currentTime=o.trimStart;media.play().catch(error=>{if(owned())message=error.message;});}else media.pause();}if(media.currentTime<o.trimStart)media.currentTime=o.trimStart;media.volume=o.volume;}
 async function menuClick(item){if(!item.enabled||!owned())return;const result=await run('menu',{menuId:null});if(result?.status==='applied'&&owned())await request(item.request.command,item.request.target,item.request.payload);}
 function presentClick(event){if(!owned()||!session.presenting||event.target.closest('audio,video,button,input,textarea'))return;run('present.step',{direction:'next'});}
 onMount(()=>{originalState=keynoteState;originalProfile=profile;originalWindow=actualWindow;originalWindowId=windowId;originalController=controller;originalSession=session;const view=createKeynoteNativeView({getRoot:()=>root,getState:()=>keynoteState,getSession:()=>session,getProfile:()=>profile,getWindow:()=>actualWindow,getController:()=>controller,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>keynoteMenus(profile,keynoteState,windowId)});registerView?.(windowId,view);return()=>{retired=true;view.destroy();registerView?.(originalWindowId,null,view);};});
 const documentFonts=createDocumentFonts({getShared:name=>getShared(name),getFile:id=>getFile(id),getRoot:()=>root,getOwner:()=>[keynoteState,profile,actualWindow,windowId,session]});
</script>
<section bind:this={root} class="keynote-app" class:legacy={cap.legacy} class:windows={cap.windows} class:golden={cap.golden} class:presenting={session?.presenting} class:inactive={!active} data-keynote-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="-1" onkeydown={key}>
 <header class="keynote-titlebar">
  {#if !cap.windows}<WindowControls active={active} onclose={()=>run('close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
  <strong>{doc?.content.title??cap.label}</strong><span>{doc?.dirty?'Edited':doc?.fileId?'PowerPoint Document':'Theme Chooser'}</span>{#if cap.windows}<b>Keynote Local Equivalent</b><button data-keynote-control="window:minimize" aria-label="Minimize" disabled={!available||!active||typeof controls.onminimize!=='function'} onclick={controls.onminimize}>−</button><button data-keynote-control="window:zoom" aria-label="Maximize or restore" disabled={!available||!active||typeof controls.onzoom!=='function'} onclick={controls.onzoom}>□</button><button data-keynote-control="window:close" aria-label="Close" onclick={()=>run('close')}>×</button>{/if}
 </header>
 {#if cap.windows}<nav class="keynote-local-menubar" aria-label="Local application menus">{#each menus as menu}<button data-keynote-control={`menu:${menu.id}`} aria-haspopup="menu" onclick={()=>run('menu',{menuId:session?.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if session?.menu}<div class="keynote-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" disabled={!item.enabled} data-keynote-control={`menuitem:${item.id}`} onclick={()=>menuClick(item)}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 {#if !session?.presenting}
 <div class="keynote-toolbar" inert={!available||!active||session?.panel!=='none'}>
  <button data-keynote-control="view" onclick={()=>run('view',{navigator:!session.navigator})}><b>▤</b>View</button>
  <select data-keynote-control="zoom" aria-label="Zoom" value={session?.zoom??.75} onchange={e=>run('view',{zoom:Number(e.currentTarget.value)})}>{#each [.25,.5,.75,1,1.25,1.5,2] as zoom}<option value={zoom}>{Math.round(zoom*100)}%</option>{/each}</select>
  <button data-keynote-control="add-slide" disabled={!slide} onclick={()=>run('slide.add')}><b>＋</b>Add Slide</button>
  <button data-keynote-control="play" disabled={!slide} onclick={()=>run('present',{playing:true})}><b>▶</b>Play</button>
  <span class="keynote-toolbar-space"></span>
  <button data-keynote-control="text" disabled={!slide} onclick={()=>run('object.add',{type:'text'})}><b>Ｔ</b>Text</button>
  <button data-keynote-control="shape" disabled={!slide} onclick={()=>run('object.add',{type:'shape',shape:'rect'})}><b>●■</b>Shape</button>
  <button data-keynote-control="chart" disabled={!slide} onclick={()=>run('object.add',{type:'chart'})}><b>▥</b>Chart</button>
  <button data-keynote-control="media" disabled={!slide} onclick={()=>run('media.insert')}><b>▧</b>Media</button>
  <button data-keynote-control="share" disabled={!doc} onclick={()=>run('share')}><b>⇧</b>Share</button>
  <span class="keynote-toolbar-space"></span>
  {#each ['format','animate','document'] as inspector}<button data-keynote-control={`inspector:${inspector}`} class:selected={session?.inspector===inspector} onclick={()=>run('view',{inspector})}><b>{inspector==='format'?'☷':inspector==='animate'?'◇':'▤'}</b>{inspector[0].toUpperCase()+inspector.slice(1)}</button>{/each}
 </div>
 {#if keynoteState.documents.length}<div class="keynote-documents" inert={!available||!active||session?.panel!=='none'}>{#each keynoteState.documents as d (d.id)}<button data-keynote-control={`document:${d.id}`} class:selected={doc===d} onclick={()=>run('document.select',{documentId:d.id})}>{d.content.title}{d.dirty?' •':''}</button>{/each}<button data-keynote-control="new" onclick={()=>run('panel',{panel:'themes'})}>＋</button><button data-keynote-control="save" disabled={!doc} onclick={()=>run('save')}>Save .pptx</button><button data-keynote-control="export" disabled={!doc} onclick={()=>run('panel',{panel:'export'})}>Export…</button></div>{/if}
 {/if}
 <div class="keynote-workspace" inert={!available||!active||session?.panel!=='none'}>
 {#if session?.navigator&&!session?.presenting&&doc}<aside class="keynote-navigator" data-keynote-area="slides" aria-label="Slide navigator">{#each doc.content.slides as s,index (s.id)}<div class="keynote-slide-row" class:selected={slide===s}><span>{index+1}</span><button data-keynote-control={`slide:${s.id}`} data-keynote-slide={s.id} aria-label={`Slide ${index+1}: ${s.name}`} onclick={()=>run('slide.select',{slideId:s.id})}><span class="keynote-thumb" style={`background:${s.background}`}>{@html thumbnailSVG(s)}{#if s.objects.some(o=>['audio','video'].includes(o.type))}<small aria-label="Contains real audiovisual media">▶</small>{/if}</span></button></div>{/each}<div class="keynote-slide-actions"><button aria-label="Duplicate slide" onclick={()=>run('slide.duplicate')}>⧉</button><button aria-label="Delete slide" disabled={doc.content.slides.length===1} onclick={()=>run('slide.delete')}>−</button><button aria-label="Move slide up" disabled={doc.content.slides.indexOf(slide)===0} onclick={()=>run('slide.move',{index:doc.content.slides.indexOf(slide)-1})}>↑</button><button aria-label="Move slide down" disabled={doc.content.slides.indexOf(slide)===doc.content.slides.length-1} onclick={()=>run('slide.move',{index:doc.content.slides.indexOf(slide)+1})}>↓</button></div></aside>{/if}
 <main class="keynote-editor" data-keynote-area="canvas">
 {#if slide&&doc}
 {#if session.presenting}<div class="keynote-presentation-bar"><span>{doc.content.title} · {doc.content.slides.indexOf(slide)+1}/{doc.content.slides.length}</span><button data-keynote-control="previous" onclick={()=>run('present.step',{direction:'previous'})}>Previous</button><button data-keynote-control="next" onclick={()=>run('present.step',{direction:'next'})}>Next</button><button data-keynote-control="stop" onclick={()=>run('present',{playing:false})}>End Slideshow (Esc)</button></div>{/if}
 <div class="keynote-canvas-space" style={session.presenting?'':`min-width:${doc.content.width*session.zoom+50}px;min-height:${doc.content.height*session.zoom+50}px;`}>
 {#key `${slide.id}:${session.presenting?session.presentationStep:0}`}
 <div class="keynote-slide-canvas" class:play-fade={session.presenting&&slide.transition==='fade'} class:play-push={session.presenting&&slide.transition==='push'} class:play-wipe={session.presenting&&slide.transition==='wipe'} data-keynote-slide-canvas data-keynote-slide={slide.id} style={`background:${slide.background};aspect-ratio:${doc.content.width}/${doc.content.height};width:${session.presenting?'min(100%, 1200px)':doc.content.width*session.zoom+'px'};--keynote-duration:${slide.transitionDuration}s;`} role="group" aria-label={`Slide ${doc.content.slides.indexOf(slide)+1}: ${slide.name}`} onclick={presentClick}>
 {#each slide.objects as o (o.id)}
 <div class="keynote-object" class:selected={!session.presenting&&object===o} data-keynote-object={o.id} style={position(o)} role="group" aria-label={`${o.type} object`} onpointerdown={e=>pointerStart(e,o)} onpointermove={pointerMove} onpointerup={pointerEnd} onpointercancel={()=>drag=null}>
 {#if o.type==='text'}
  {#if !session.presenting&&object===o}<textarea data-keynote-control={`text:${o.id}`} aria-label="Edit slide text" style={`font-family:${documentFonts.css(o.font,o.bold,o.italic)};font-size:${o.size*session.zoom}px;color:${o.color};font-weight:${o.bold?'bold':'normal'};font-style:${o.italic?'italic':'normal'};text-align:${o.align};`} value={o.text} oninput={e=>update({text:e.currentTarget.value})}></textarea>
  {:else}<button class="keynote-text-object" data-keynote-control={`object:${o.id}`} style={`font-family:${documentFonts.css(o.font,o.bold,o.italic)};font-size:${session.presenting?'clamp(10px, '+o.size/doc.content.width*100+'cqw, '+o.size*1.25+'px)':o.size*session.zoom+'px'};color:${o.color};font-weight:${o.bold?'bold':'normal'};font-style:${o.italic?'italic':'normal'};text-align:${o.align};`} onclick={()=>session.presenting?run('present.step',{direction:'next'}):run('object.select',{objectId:o.id})}>{o.text}</button>{/if}
 {:else if o.type==='shape'}<button class="keynote-shape-object" data-keynote-control={`object:${o.id}`} aria-label={`Select ${o.shape}`} onclick={()=>session.presenting?run('present.step',{direction:'next'}):run('object.select',{objectId:o.id})}><svg viewBox={`0 0 ${o.width} ${o.height}`} preserveAspectRatio="none" aria-hidden="true">{#if o.shape==='ellipse'}<ellipse cx={o.width/2} cy={o.height/2} rx={o.width/2-2} ry={o.height/2-2} fill={o.fill} stroke={o.stroke} stroke-width="2"/>{:else if o.shape==='triangle'}<polygon points={`${o.width/2},2 ${o.width-2},${o.height-2} 2,${o.height-2}`} fill={o.fill} stroke={o.stroke} stroke-width="2"/>{:else if o.shape==='line'}<line x1="0" y1="0" x2={o.width} y2={o.height} stroke={o.stroke} stroke-width="2"/>{:else}<rect x="1" y="1" width={o.width-2} height={o.height-2} fill={o.fill} stroke={o.stroke} stroke-width="2"/>{/if}</svg></button>
 {:else if o.type==='image'}<button class="keynote-image-object" data-keynote-control={`object:${o.id}`} aria-label="Select image" onclick={()=>session.presenting?run('present.step',{direction:'next'}):run('object.select',{objectId:o.id})}><img alt="Imported local slide image" draggable="false" src={o.content} style={`position:absolute;width:${100/(1-o.crop.left-o.crop.right)}%;height:${100/(1-o.crop.top-o.crop.bottom)}%;left:${-o.crop.left*100/(1-o.crop.left-o.crop.right)}%;top:${-o.crop.top*100/(1-o.crop.top-o.crop.bottom)}%;`}/></button>
 {:else if o.type==='chart'}<button class="keynote-image-object" data-keynote-control={`object:${o.id}`} aria-label="Select chart" onclick={()=>session.presenting?run('present.step',{direction:'next'}):run('object.select',{objectId:o.id})}><img alt="Chart of authored values" src={chartURL(o)}/></button>
 {:else if o.type==='video'}<video data-keynote-media={o.id} data-keynote-control={`media:${o.id}`} src={o.content} controls preload="metadata" onloadedmetadata={e=>mediaLoaded(e,o)} ontimeupdate={e=>mediaTime(e,o)} onended={e=>mediaTime(e,o)}></video>{#if !session.presenting}<button class="keynote-media-select" data-keynote-control={`object:${o.id}`} onclick={()=>run('object.select',{objectId:o.id})}>Movie Settings</button>{/if}
 {:else}<audio data-keynote-media={o.id} data-keynote-control={`media:${o.id}`} src={o.content} controls preload="metadata" onloadedmetadata={e=>mediaLoaded(e,o)} ontimeupdate={e=>mediaTime(e,o)} onended={e=>mediaTime(e,o)}></audio>{#if !session.presenting}<button class="keynote-media-select" data-keynote-control={`object:${o.id}`} onclick={()=>run('object.select',{objectId:o.id})}>Audio Settings</button>{/if}{/if}
 </div>{/each}
 </div>{/key}</div>
 {#if session.notes&&!session.presenting}<div class="keynote-notes"><label>Presenter Notes<textarea data-keynote-control="notes" value={slide.notes} maxlength="32768" oninput={e=>run('slide.update',{notes:e.currentTarget.value})}></textarea></label></div>{/if}
 {:else}<div class="keynote-empty"><h2>Create a presentation</h2><p>Choose a theme to begin with editable title slides, or open a genuine PowerPoint file.</p><button data-keynote-control="choose-theme" onclick={()=>run('panel',{panel:'themes'})}>Choose a Theme…</button><button data-keynote-control="open" onclick={()=>run('open')}>Open…</button></div>{/if}
 </main>
 {#if doc&&!session.presenting}<aside class="keynote-inspector" data-keynote-area="inspector">
 {#if session.inspector==='animate'}<h2>Slide Transition</h2><label>Effect<select data-keynote-control="transition" value={slide.transition} onchange={e=>run('slide.update',{transition:e.currentTarget.value})}>{#each ['none','fade','push','wipe'] as value}<option value={value}>{value==='fade'?'Dissolve':value[0].toUpperCase()+value.slice(1)}</option>{/each}</select></label><label>Duration<input data-keynote-control="transition-duration" type="number" min="0.1" max="10" step="0.1" value={slide.transitionDuration} onchange={e=>run('slide.update',{transitionDuration:Number(e.currentTarget.value)})}/> seconds</label><p>Transitions play locally between actual slides. Advance on click or arrow key; Escape ends playback.</p><button data-keynote-control="preview-transition" onclick={()=>run('present',{playing:true})}>Preview</button>
 {:else if session.inspector==='document'}<h2>Document</h2><label>Title<input data-keynote-control="document-title" maxlength="256" value={doc.content.title} onchange={e=>run('document.rename',{title:e.currentTarget.value})}/></label><p>Slide Size: {doc.content.width} × {doc.content.height}</p><p>Theme: {doc.content.theme}</p><button data-keynote-control="print" onclick={()=>run('print')}>Print…</button><button onclick={()=>run('panel',{panel:'export'})}>Export To…</button><p>{cap.disclosure}</p>
 {:else if object}<div class="keynote-inspector-tabs"><b>Style</b><b>{object.type==='video'?'Movie':object.type==='audio'?'Audio':object.type==='image'?'Image':object.type==='text'?'Text':'Shape'}</b><b>Arrange</b></div>
  {#if object.type==='text'}<h2>Text</h2><label>Typeface<select data-keynote-control="font" value={object.font} onchange={e=>update({font:e.currentTarget.value})}>{#each documentFonts.choices(object.font) as font}<option disabled={!documentFonts.has(font)} value={font}>{font}{!documentFonts.has(font)?' (unavailable)':''}</option>{/each}</select></label><label>Size<input data-keynote-control="font-size" type="number" min="1" max="200" value={object.size} onchange={e=>update({size:Number(e.currentTarget.value)})}/></label><div class="keynote-inspector-buttons"><button class:selected={object.bold} data-keynote-control="bold" onclick={()=>update({bold:!object.bold})}><b>B</b></button><button class:selected={object.italic} data-keynote-control="italic" onclick={()=>update({italic:!object.italic})}><i>I</i></button>{#each ['left','center','right'] as align}<button data-keynote-control={`align:${align}`} class:selected={object.align===align} onclick={()=>update({align})}>{align}</button>{/each}</div><label>Text Color<input data-keynote-control="text-color" type="color" value={object.color} onchange={e=>update({color:e.currentTarget.value})}/></label>
 {:else if object.type==='shape'}<h2>Shape</h2><label>Shape<select data-keynote-control="shape-type" value={object.shape} onchange={e=>update({shape:e.currentTarget.value})}>{#each ['rect','ellipse','triangle','line'] as shape}<option value={shape}>{shape}</option>{/each}</select></label><label>Fill<input data-keynote-control="fill" type="color" value={object.fill} onchange={e=>update({fill:e.currentTarget.value})}/></label><label>Border<input data-keynote-control="stroke" type="color" value={object.stroke} onchange={e=>update({stroke:e.currentTarget.value})}/></label>
 {:else if object.type==='image'}<h2>Image Crop</h2>{#each ['left','top','right','bottom'] as edge}<label>{edge}<input data-keynote-control={`crop:${edge}`} type="number" min="0" max="0.99" step="0.01" value={object.crop[edge]} onchange={e=>update({crop:{...object.crop,[edge]:Number(e.currentTarget.value)}})}/></label>{/each}<button data-keynote-control="crop-reset" onclick={()=>update({crop:{left:0,top:0,right:0,bottom:0}})}>Reset Crop</button>
 {:else if object.type==='chart'}<h2>Chart Data</h2><label>Chart<select data-keynote-control="chart-kind" value={object.kind} onchange={e=>update({kind:e.currentTarget.value})}><option value="bar">Bar</option><option value="line">Line</option><option value="pie">Pie</option></select></label><label>Data (label, value — one row per line)<textarea data-keynote-control="chart-data" value={object.labels.map((label,i)=>`${label}, ${object.values[i]}`).join('\n')} onchange={e=>{const rows=e.currentTarget.value.split('\n').map(line=>{const comma=line.lastIndexOf(',');return [line.slice(0,comma).trim(),Number(line.slice(comma+1).trim())];});update({labels:rows.map(row=>row[0]),values:rows.map(row=>row[1])});}}></textarea></label><p>Author actual chart labels and values together.</p>
 {:else}<h2>{object.type==='video'?'Movie':'Audio'} Settings</h2><p>Actual duration: {object.duration.toFixed(2)} s</p><label>Start<input data-keynote-control="trim-start" type="number" step="0.01" min="0" max={object.duration} value={object.trimStart} onchange={e=>update({trimStart:Number(e.currentTarget.value)})}/></label><label>End<input data-keynote-control="trim-end" type="number" step="0.01" min="0" max={object.duration} value={object.trimEnd} onchange={e=>update({trimEnd:Number(e.currentTarget.value)})}/></label><label>Volume<input data-keynote-control="volume" type="range" min="0" max="1" step="0.01" value={object.volume} oninput={e=>update({volume:Number(e.currentTarget.value)})}/></label><label><input data-keynote-control="loop" type="checkbox" checked={object.loop} onchange={e=>update({loop:e.currentTarget.checked})}/> Loop trimmed segment</label><button data-keynote-control="media-play" onclick={()=>run('media.play',{playing:true})}>Play</button><button data-keynote-control="media-pause" onclick={()=>run('media.play',{playing:false})}>Pause</button><p>Playback uses the real imported WAV/WebM bytes. Embedded media PPTX export is unavailable.</p>{/if}
 <h2>Arrange</h2><div class="keynote-geometry">{#each ['x','y','width','height','rotation'] as field}<label>{field}<input data-keynote-control={`geometry:${field}`} type="number" min={field==='x'||field==='y'?-960:field==='rotation'?-360:1} max={field==='rotation'?360:1920} value={object[field]} onchange={e=>update({[field]:Number(e.currentTarget.value)})}/></label>{/each}</div><label>Opacity<input data-keynote-control="opacity" type="range" min="0" max="1" step="0.01" value={object.opacity} oninput={e=>update({opacity:Number(e.currentTarget.value)})}/></label><div class="keynote-inspector-buttons"><button data-keynote-control="front" onclick={()=>run('object.order',{direction:'front'})}>Front</button><button data-keynote-control="back" onclick={()=>run('object.order',{direction:'back'})}>Back</button><button data-keynote-control="delete-object" onclick={()=>run('object.delete')}>Delete</button></div>
 {:else}<h2>Slide Layout</h2><label>Name<input data-keynote-control="slide-name" maxlength="256" value={slide.name} onchange={e=>run('slide.update',{name:e.currentTarget.value})}/></label><label>Background<input data-keynote-control="background" type="color" value={slide.background} onchange={e=>run('slide.update',{background:e.currentTarget.value})}/></label><p>Select a text box, shape or media object to edit its properties.</p>{/if}
 {#if object}<button data-keynote-control="deselect" onclick={()=>run('object.select',{objectId:null})}>Slide Settings</button>{/if}
 </aside>{/if}
 </div>
 {#if session?.panel!=='none'}<div class="keynote-sheet-backdrop"><section class="keynote-sheet" class:theme-chooser={session?.panel==='themes'} role="dialog" aria-modal="true" aria-label={session?.panel==='themes'?'Choose a Theme':session?.panel==='save'?'Save Presentation As':session?.panel==='export'?'Export Your Presentation':session?.panel==='close'?'Save Changes':'Keynote Help'}>
 {#if session?.panel==='themes'}<h2>Choose a Theme</h2><div class="keynote-theme-heading"><b>Basic</b><span>Wide · 16:9</span></div><div class="keynote-themes">{#each themes as t}<button class:selected={theme===t.id} data-keynote-control={`theme:${t.id}`} onclick={()=>theme=t.id}><span style={`background:${t.color};color:${t.ink}`}><strong>Title</strong><small>Subtitle</small></span>{t.label}</button>{/each}</div><label>Name<input data-keynote-control="new-title" maxlength="256" bind:value={title}/></label><p>Editable local themes. Apple proprietary theme bundles are not imported.</p><div class="keynote-sheet-buttons"><button data-keynote-control="theme-open" onclick={()=>run('open')}>Open…</button><button data-keynote-control="theme-cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button class="keynote-default" data-keynote-control="theme-create" disabled={!title.trim()} onclick={()=>run('new',{theme,title})}>Create</button></div>
 {:else if session?.panel==='save'}<h2>Save Presentation As</h2><p>Save a genuine PowerPoint copy in shared Documents. The document will use this new original File for subsequent saves. Apple .key archives are unavailable.</p><label>Name<input data-keynote-control="save-name" maxlength="240" bind:value={exportName}/></label><div class="keynote-sheet-buttons"><button data-keynote-control="save-cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button class="keynote-default" data-keynote-control="save-copy" disabled={!exportName.trim()} onclick={()=>run('save',{name:exportName,saveAs:true})}>Save .pptx</button></div>
 {:else if session?.panel==='export'}<h2>Export Your Presentation</h2><div class="keynote-export-tabs">{#each ['pptx','pdf','png','svg'] as format}<button data-keynote-control={`export:${format}`} class:selected={format===exportFormat} onclick={()=>exportFormat=format}>{format==='pptx'?'PowerPoint':format.toUpperCase()}</button>{/each}</div><p>{exportFormat==='pptx'?'Genuine Office Open XML (.pptx). Embedded audio/video and unsupported crop/rotation/opacity are rejected without changing the document.':exportFormat==='pdf'?'Genuine multipage PDF: each actual slide is rendered to PNG and embedded as a page. Audiovisual playback is not a static PDF feature.':'Exports the selected actual slide. PNG contains rendered pixels; SVG preserves authored text, shapes and genuine image data. Audiovisual objects cannot be exported.'}</p><label>Name<input data-keynote-control="export-name" maxlength="240" bind:value={exportName}/></label><div class="keynote-sheet-buttons"><button data-keynote-control="export-cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button class="keynote-default" data-keynote-control="export-save" disabled={!exportName.trim()} onclick={()=>run('export',{format:exportFormat,name:exportName})}>Export</button></div>
 {:else if session?.panel==='close'}<h2>Do you want to save changes to “{doc?.content.title}”?</h2><p>Your changes will be lost if you do not save. Save writes a genuine .pptx, not Apple .key.</p><div class="keynote-sheet-buttons"><button data-keynote-control="close-discard" onclick={()=>run('close',{decision:'discard'})}>Don't Save</button><button data-keynote-control="close-cancel" onclick={()=>run('close',{decision:'cancel'})}>Cancel</button><button class="keynote-default" data-keynote-control="close-save" onclick={()=>run('close',{decision:'save'})}>Save</button></div>
 {:else}<h2>{cap.label}</h2><p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>{cap.disclosure}</p><p>Choose a theme, add or reorder slides, edit text, shapes, charts and actual PNG/JPEG/WAV/WebM media. Select an object for Format settings; drag its surface or use arrow keys to arrange it. Audio/movie trim, volume and looping act on genuine browser playback.</p><p>Play advances on click, Space or arrow keys. Home/End selects the first/last slide, Escape stops. Presenter notes are authored per slide. Save/Open supports actual PowerPoint; print/share/pickers and clipboard use the single scene authority. No host presentation controls, remote collaboration or fabricated file formats.</p><button data-keynote-control="help-done" onclick={()=>run('panel',{panel:'none'})}>Done</button>{/if}
 {#if message}<p class="keynote-error" role="alert">{message}</p>{/if}</section></div>{/if}
 {#if !session?.presenting}<footer class="keynote-status" role="status"><span>{documentFonts.error||message||cap.disclosure}</span><span>{doc?`${doc.content.slides.length} slides`:''}</span></footer>{/if}
</section>
